        vec2 l2s( vec2 v ) {
            return (vec4(v,0.,1.)*acLayerToScreen).xy;
        }

        void main() {

            vec2 parr = vec2(0., 0.);
            vec2 position = vec2(0., 0.);
            int direction = 3;
            float stretch = 0.;
            float scale = detail * 5.;
            float offs = 0.15;
            float intensity = strength * 0.1;
            bool screenSpace = false;

            vec2 st;

            if( screenSpace ) {
                st = acScreenNorm;
                st.x *= acScreenSize.x/acScreenSize.y;
            } else {
                st = acLayerNorm;
                st.x *= acLayerSize.x/acLayerSize.y;
            }

            st += position*vec2(-1.,1.)/500.; //vec2(offsx,offsy);

            //st += mod(vec2(4.365,7.701));

            vec2 parallax = parr*vec2(-1.,1.)/100.; //vec2(parrx, parry);

            vec2 scaleVec;
            if( stretch < 0.0 ) {
                scaleVec = vec2(scale-stretch,scale);
            } else {
                scaleVec = vec2(scale,scale+stretch);
            }

            float p = turbulence((st-0.5)*scaleVec+0.5, int(octaves), parallax, evolution + 7391.935*seed);

            //p -= 0.2;
            p += (offs-0.25);
            p *= intensity;

            vec2 uv = screenSpace ? acScreenNorm : acLayerNorm;

            if( direction==0 ) {
                // X
                uv.x += p;
            } else if( direction == 1 ) {
                // Y
                uv.y += p;
            } else if (direction == 2 ) {
                // XY
                float q = turbulence((st-0.5)*scaleVec+0.5, int(octaves), parallax, evolution + 3937.7249*(seed+6.3379));
                //q -= 1.;
                q += (offs-0.25);
                q *= intensity;
                uv.x += p;
                uv.y += q;
            } else {
                // R
                uv += normalize(uv-0.5)*p;
            }

            if( !screenSpace ) {
                uv = l2s(uv);
            }

            vec4 original = texture2DCv(inputImg.texture,acScreenNorm);
            vec4 displaced = texture2DCv(inputImg.texture,uv);

            gl_FragColor = original * displaced.a;
        }

