        float sdSide( vec3 p, vec3 b, vec3 s, float t, float o, float sm, int mode, float progress, float sideOutset ) {

            if( mode == 1 ) {           // Hidden
                return 1000000.0;
            }

            p += s*(b + o - t*0.5);
            b *= 1. - abs(s);
            b += t * abs(s) * 0.5;

            sm = min(sm,t/2.);
            p += s*(sideOutset-0.5)*5.;

            if( mode == 2 ) {       // Square cutout
                vec3 bb = b;
                bb *= 1. - abs(s);
                bb *= progress;
                bb += t * abs(s);
                return opSmoothSubtraction(sdBox(p,bb), (sdBox(p,b-sm)-sm),sm);
            } else if( mode == 3 ) {            // Circle Cutout
                vec3 pp = p;
                pp *= 1. - abs(s);
                vec3 bb = b;
                bb *= 1. - abs(s);
                float cc = length(pp)/length(bb)-(progress-0.01);
                return opSmoothSubtraction(cc, sdBox(p,b-sm)-sm, sm);
