        float snoise(vec3 v)
          {
          const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
          const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

        // First corner
          vec3 i  = floor(v + dot(v, C.yyy) );
          vec3 x0 =   v - i + dot(i, C.xxx) ;

        // Other corners
          vec3 g = step(x0.yzx, x0.xyz);
          vec3 l = 1.0 - g;
          vec3 i1 = min( g.xyz, l.zxy );
          vec3 i2 = max( g.xyz, l.zxy );

          //   x0 = x0 - 0.0 + 0.0 * C.xxx;
          //   x1 = x0 - i1  + 1.0 * C.xxx;
          //   x2 = x0 - i2  + 2.0 * C.xxx;
          //   x3 = x0 - 1.0 + 3.0 * C.xxx;
          vec3 x1 = x0 - i1 + C.xxx;
          vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
          vec3 x3 = x0 - D.yyy;      // -1.0+3.0*C.x = -0.5 = -D.y

        // Permutations
          i = mod289(i);
          vec4 p = permute( permute( permute(
                     i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
                   + i.y + vec4(0.0, i1.y, i2.y, 1.0 ))
                   + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

        // Gradients: 7x7 points over a square, mapped onto an octahedron.
        // The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
          float n_ = 0.142857142857; // 1.0/7.0
          vec3  ns = n_ * D.wyz - D.xzx;

          vec4 j = p - 49.0 * floor(p * ns.z * ns.z);  //  mod(p,7*7)

          vec4 x_ = floor(j * ns.z);
          vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

          vec4 x = x_ *ns.x + ns.yyyy;
          vec4 y = y_ *ns.x + ns.yyyy;
          vec4 h = 1.0 - abs(x) - abs(y);

          vec4 b0 = vec4( x.xy, y.xy );
          vec4 b1 = vec4( x.zw, y.zw );

          //vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
          //vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
          vec4 s0 = floor(b0)*2.0 + 1.0;
          vec4 s1 = floor(b1)*2.0 + 1.0;
          vec4 sh = -step(h, vec4(0.0));

          vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
          vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

          vec3 p0 = vec3(a0.xy,h.x);
          vec3 p1 = vec3(a0.zw,h.y);
          vec3 p2 = vec3(a1.xy,h.z);
          vec3 p3 = vec3(a1.zw,h.w);

        //Normalise gradients
          vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
          p0 *= norm.x;
          p1 *= norm.y;
          p2 *= norm.z;
          p3 *= norm.w;

        // Mix final noise value
          vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
          m = m * m;
          return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1),
                                        dot(p2,x2), dot(p3,x3) ) );
        }

        float snoise(vec2 v) {

            // Precompute values for skewed triangular grid
            const vec4 C = vec4(0.211324865405187,
                                // (3.0-sqrt(3.0))/6.0
                                0.366025403784439,
                                // 0.5*(sqrt(3.0)-1.0)
                                -0.577350269189626,
                                // -1.0 + 2.0 * C.x
                                0.024390243902439);
                                // 1.0 / 41.0

            // First corner (x0)
            vec2 i  = floor(v + dot(v, C.yy));
            vec2 x0 = v - i + dot(i, C.xx);

            // Other two corners (x1, x2)
            vec2 i1 = vec2(0.0);
            i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
            vec2 x1 = x0.xy + C.xx - i1;
            vec2 x2 = x0.xy + C.zz;

            // Do some permutations to avoid
            // truncation effects in permutation
            i = mod289(i);
            vec3 p = permute(
                    permute( i.y + vec3(0.0, i1.y, 1.0))
                        + i.x + vec3(0.0, i1.x, 1.0 ));

            vec3 m = max(0.5 - vec3(
                                dot(x0,x0),
                                dot(x1,x1),
                                dot(x2,x2)
                                ), 0.0);

            m = m*m ;
            m = m*m ;

            // Gradients:
            //  41 pts uniformly over a line, mapped onto a diamond
            //  The ring size 17*17 = 289 is close to a multiple
            //      of 41 (41*7 = 287)

            vec3 x = 2.0 * fract(p * C.www) - 1.0;
            vec3 h = abs(x) - 0.5;
            vec3 ox = floor(x + 0.5);
            vec3 a0 = x - ox;

            // Normalise gradients implicitly by scaling m
            // Approximation of: m *= inversesqrt(a0*a0 + h*h);
            m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

            // Compute final noise value at P
            vec3 g = vec3(0.0);
            g.x  = a0.x  * x0.x  + h.x  * x0.y;
            g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
            return 130.0 * dot(m, g);
        }

        float turbulence (in vec2 st, in int OCTAVES, in vec2 parallax, in float evolution) {
            // Initial values
            float value = 0.0;
            float amplitude = .5;
            float frequency = 0.;
            //
            // Loop of octaves
            for (int i = 0; i < OCTAVES; i++) {
                value += amplitude * abs(snoise(vec3(st,evolution)));
                st *= 2.;
                st += parallax;
                amplitude *= .5;
            }
            return value;
        }

        vec2 l2s( vec2 v ) {
            return (vec4(v,0.,1.)*acLayerToScreen).xy;
        }

        void main() {

            vec2 st;
            vec2 center;

            if( screenSpace ) {
                st = acScreenNorm;
                st.x *= acScreenSize.x/acScreenSize.y;
                center = vec2(acScreenSize.x/acScreenSize.y, 1.0)*0.5;
            } else {
                st = acLayerNorm;
                st.x *= acLayerSize.x/acLayerSize.y;
                center = vec2(acLayerSize.x/acLayerSize.y, 1.0)*0.5;
            }

            st += position*vec2(-1.,1.)/500.; //vec2(offsx,offsy);

            //st += mod(vec2(4.365,7.701));

            vec2 parallax = parr*vec2(-1.,1.)/100.; //vec2(parrx, parry);

            vec2 scaleVec;
            scaleVec = vec2(scale*stretch.y,scale*stretch.x);
            if(screenSpace) {
                float t = scaleVec.x;
                scaleVec.x = scaleVec.y;
                scaleVec.y = t;
            }
            vec2 sampleCoord;

            if( singleAxis ) {
                if( direction==0 ) {
                    // X
                    sampleCoord = vec2(0.,st.y - center.y);
                } else if( direction == 1 ) {
                    // Y
                    sampleCoord = vec2(st.x - center.x,0.);
                } else if (direction == 2 ) {
                    // XY
                    sampleCoord = st - center;
                } else if (direction == 4 ) {
                    // φr
                    sampleCoord = st - center;
                } else if (direction == 5 ) {
                    // φ
                    sampleCoord = vec2(0.,length(st-center));
                } else {
                    // R
                    float tt = abs(atan(st.x-center.x,st.y-center.y)/6.28318)*2.;
                    sampleCoord = vec2(tt,0.);
                }
            } else {
                sampleCoord = st - center;
            }

            float p = turbulence((sampleCoord-0.5)/scaleVec+0.5, int(octaves), parallax, evolution + 7391.935*seed);

            p += (offs-0.25);
            p *= intensity * 2.0;

            vec2 uv = screenSpace ? acScreenNorm : acLayerNorm;
            vec2 v = uv;

            if( direction==0 ) {
                // X
                v.x += p;
            } else if( direction == 1 ) {
                // Y
                v.y += p;
            } else if (direction == 2 ) {
                // XY
                float q = turbulence((sampleCoord)/scaleVec+0.5, int(octaves), parallax, evolution + 3937.7249*(seed+6.3379));
                //q -= 1.;
                q += (offs-0.25);
                q *= intensity * 2.0;
                v.x += p;
                v.y += q;
            } else if (direction == 4 ) {
                // φr
                float q = turbulence((sampleCoord)/scaleVec+0.5, int(octaves), parallax, evolution + 3937.7249*(seed+6.3379));
                q += (offs-0.25);
                q *= intensity * 2.0;
                float cq = cos(q);
                float sq = sin(q);
                v += normalize(v-0.5)*p;
                v *= mat2(cq,sq,-sq,cq);
            } else if (direction == 5 ) {
                // φ
                float cq = cos(p);
                float sq = sin(p);
                v *= mat2(cq,sq,-sq,cq);
            } else {
                // R
                v += normalize(v-0.5)*p;
            }
            v -= uv;


            vec2 texelSize = 1.0 / acScreenSize;
            float speed = length(v / texelSize);
            int nSamples = int(clamp(speed, 1.01, 100.01));
            vec4 outColor = texture2DCv(inputImg.texture,acScreenNorm);
            vec2 vnorm = normalize(v)*texelSize*speed;
            vec2 offsetScale = vec2(1., 1.);
            if( acScreenSize.y > acScreenSize.x ) {
                offsetScale.x *= acScreenSize.x / acScreenSize.y;
            } else {
                offsetScale.y *= acScreenSize.y / acScreenSize.x;
            }

            for(int i=1; i<nSamples; i++ ) {
                vec2 offset = vnorm * float(i) / float(nSamples - 1);
                offset *= offsetScale;
                vec2 sample;
                if( screenSpace ) {
                    sample = acScreenNorm;
                } else {
                    sample = acLayerNorm;
                }
                sample = sample + offset;

                if( !screenSpace ) {
                    sample = (vec4(sample,0.0,1.0) * acLayerToScreen).xy;
                }

                outColor += texture2DCv(inputImg.texture, sample);
            }
            gl_FragColor = outColor/float(nSamples);
        }

